CREATE FUNCTION public.sync_next_action() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE next_row public.activities; BEGIN SELECT * INTO next_row FROM public.activities WHERE lead_id=NEW.lead_id AND status='pendente' ORDER BY due_at LIMIT 1; UPDATE public.leads SET next_action=COALESCE(next_row.title,''),next_at=next_row.due_at WHERE id=NEW.lead_id AND (next_action IS DISTINCT FROM COALESCE(next_row.title,'') OR next_at IS DISTINCT FROM next_row.due_at); RETURN NEW; END $$;
CREATE TRIGGER activity_sync AFTER INSERT OR UPDATE OF status,due_at,title ON public.activities FOR EACH ROW WHEN (NEW.type NOT IN ('Registro','Atualização','Etapa','Nota')) EXECUTE FUNCTION public.sync_next_action();
CREATE FUNCTION public.note_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.activities(lead_id,type,title,status,observation) VALUES(NEW.lead_id,'Nota','Nota interna adicionada','concluída',NEW.content); RETURN NEW; END $$;
CREATE TRIGGER note_audit AFTER INSERT ON public.notes FOR EACH ROW EXECUTE FUNCTION public.note_history();
CREATE FUNCTION public.lead_contact() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.contacts(lead_id,name,phone,instagram) VALUES(NEW.id,NEW.decision_maker,NEW.phone,NEW.instagram); INSERT INTO public.conversations(lead_id,channel) VALUES(NEW.id,NEW.channel); RETURN NEW; END $$;
CREATE TRIGGER create_lead_contact AFTER INSERT ON public.leads FOR EACH ROW EXECUTE FUNCTION public.lead_contact();